INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(3600, 0, 36, 0, 0, 0, 'Alterac Mountains', 'These cold peaks between Lordaeron and the Hillsbrad foothills were once a proud human kingdom. Alterac began as a city-state of the old Arathorian empire, but in the Second War its king, Aiden Perenolde, secretly struck a bargain with Orgrim Doomhammer and let the Horde march through his mountain passes unopposed. When the treason came to light, King Terenas marched into Alterac, declared martial law and deposed him. The kingdom never recovered. Today the Crushridge ogres squat in the ruined capital, while the Syndicate, a gang of thieves led by Alterac''s disgraced nobles under Aliden Perenolde, holds Strahnbrad and the Uplands and dreams of taking the land back. On the shore of Lordamere Lake lie the ruins of Dalaran, its wizards still patrolling the outskirts, and hidden in the eastern hills the assassins of Ravenholdt wage their own quiet war on the Syndicate. Yetis haunt the high caves, and both Southshore and Tarren Mill send agents north into the snow.', 'warcraft.wiki.gg/wiki/Kingdom_of_Alterac (Arathorian city-state, Perenolde''s pact with Doomhammer, Terenas martial law, Aliden founded the Syndicate); warcraft.wiki.gg/wiki/Alterac_Mountains (Crushridge in Alterac City, Syndicate in Strahnbrad); quest 505 description (Syndicate led by villainous nobles of fallen Alterac); quest 602 description (Dalaran crater); warcraft.wiki.gg/wiki/Ravenholdt (war on the Syndicate); DB spawns: yetis in Growless Cave and The Headland'),
(3601, 1, 36, 1, 0, 0, 'Sofera''s Naze and Corrahn''s Dagger', 'North and west of Tarren Mill, where the foothills climb into the mountains, the Syndicate keeps two rough camps at Sofera''s Naze and Corrahn''s Dagger. Footpads and thieves loiter about the tents, and a few drunkards among them sing the praises of Southshore stout. The gang''s papers pass through these camps, and the documents left lying on the camp tables are worth a careful look. In one camp lies a henchman named Valik, injured and dying, who still has something to bargain with. Southshore''s new magistrate blames the Syndicate for his predecessor''s murder, and these camps are where he looked first.', 'quest 505 description (camps in Sofera''s Naze and Corrahn''s Dagger north and west of Tarren Mill; previous magistrate assassinated); quests 510, 511 (started from Syndicate Documents gameobjects 1740, 186420); creature_text 2440 (Drunken Footpad on Southshore stout); DB spawns: Syndicate Footpad 2240, Thief 2241, Drunken Footpad 2440 in areas 1678 and 1679; quest 535 description (Valik injured and dying); DB spawn: Henchman Valik 2333 in area 1678; quest 535 description (Valik injured and dying, will talk for Southshore stout)'),
(3602, 1, 36, 2, 0, 0, 'Strahnbrad', 'Strahnbrad was a mountain village of Lordaeron, defended in the Third War by Uther and Prince Arthas when Blackrock orcs raided it for slaves to sacrifice. Many of its people died, and the rest are long gone. The Syndicate now uses the town as its main base, and spies, wizards and the mysterious shadow mages of the Argus Wake walk its streets. The gang keeps a prisoner here as well. Somewhere in the town an orc named Gol''dir lies chained in a locked room, calling out to anyone who comes near for the key to his chains, which the jailor Borhuin carries.', 'warcraft.wiki.gg/wiki/Strahnbrad (Third War Blackrock raid, Uther and Arthas; Syndicate main base; Gol''dir in a town cell, upstairs in the inn pre-Cataclysm); creature_text 2316 (Borhuin has the key); DB spawns: Syndicate Spy 2242, Syndicate Wizard 2319, Argus Shadow Mage 2318, Gol''dir 2316, Jailor Borhuin 2431 in area 280'),
(3603, 1, 36, 3, 0, 0, 'The Headland', 'The Headland is a rugged spur of the mountains above the Hillsbrad foothills, riddled with caves where ferocious yetis den. These hills have a grim history. The wizard Helcular once kept a ritual lair somewhere among them, close to becoming a lich, until a mob from Southshore found and killed him, and the yetis overran the lair. Mountain lions prowl the cliffs, and dwarves of the Stormpike clan keep a camp here on the road north. Deep in the Foothill Caverns two strange fires, the Flame of Azel and the Flame of Veraz, burn on in the dark.', 'quest 552 description (Helcular nearly a lich, lynch mob, yeti overtook his ritual lair); quest 553 description (Flame of Azel and Flame of Veraz in the Foothill Caverns); DB spawns: Flame of Azel 1768 and Flame of Veraz 1769 in area 1680; Cave Yeti 2248, Ferocious Yeti 2249; Lieutenant Haggerdin 13841, Prospector Stonehewer 13816, Thanthaldis Snowgleam 13217 in area 1680; creature_loot_template: Helcular''s Rod 3708 drops from yetis; warcraft.wiki.gg/wiki/Helcular'),
(3604, 1, 36, 4, 0, 0, 'Growless Cave', 'High in the mountains above the Foothill Caverns, Growless Cave is a den of mountain yetis and the giants of their kind. A lone fire, the Flame of Uzel, burns here in the cold. Hunters who know the old lore use it as a lure: meat burned on the flame draws Frostmaw, an elusive yeti whose white coat hides him against the snow. During the Feast of Winter Veil the cave gains a stranger tenant, a creature called the Abominable Greench, who steals holiday treats and leaves those who cross him frozen into snowmen.', 'quest 553 description (Flame of Uzel in a cave above the caverns, further north); quest 1136 description (Frostmaw, white coat, lured with a scroll); warcraft.wiki.gg/wiki/Growless_Cave (yeti, Flame of Uzel, Frostmaw lured by burning meat); quests 6983, 7043 descriptions (Greench stole the treats, turned the speaker into a snowy mess); DB spawns: Mountain Yeti 2250, Giant Yeti 2251, Flame of Uzel 1770, The Abominable Greench 13602, Strange Snowman 13636 in area 1683'),
(3605, 1, 36, 5, 0, 0, 'Ruins of Alterac', 'The capital of Alterac was emptied when the kingdom fell, and after the Third War its deserted halls were claimed by the Crushridge ogres. Their warlord Mug''thol rules from the ruins of the old palace, with warmongers, maulers and ogre mages filling the broken streets. Among them wanders Grel''borg the Miser, a greedy ogre mage who spends his days digging through the rubble for baubles; rumor says he found the Perenolde Tiara, an heirloom of the old royal family crafted by Ironforge jewelers and set with emeralds. Wrecked meat wagons near the northern gate hint that the undead once tried to storm the place.', 'warcraft.wiki.gg/wiki/Ruins_of_Alterac (deserted ruins taken by Crushridge under Mug''thol after the Third War; meat wagons near the northern gate); warcraft.wiki.gg/wiki/Mug''thol (based in the ruins of the old palace); quest 543 description (Perenolde Tiara, Ironforge jewelers, emeralds, Grel''borg); page_text 372 (Grel''borg searching for baubles); quest 504 description; DB spawns: Crushridge Warmonger 2287, Mauler 2254, Enforcer 2256, Mage 2255, Mug''thol 2257, Grel''borg 2417 in area 281'),
(3606, 1, 36, 6, 0, 0, 'Crushridge Hold', 'Beside the ruined capital, the Crushridge ogres have dug an ogre mound of their own into the mountains. Crushridge Hold is their stronghold, crowded with ogres and brutes, and their camps spill out into Slaughter Hollow and along the old road at Gallows'' Corner, where they prowl around a ruined scout tower. The slopes here are rich in mithril and truesilver, and at least one bold trader in engineering supplies has set up shop in Slaughter Hollow. Southshore pays bounties on ogre knucklebones, fearing that if the Crushridge grow comfortable here they will move down into the foothills next.', 'quest 500 description (ogre mound near the ruined city; fear they will move into the foothills); warcraft.wiki.gg/wiki/Crushridge_clan (Crushridge Hold, Slaughter Hollow); warcraft.wiki.gg/wiki/Gallows''_Corner (crossroads near the ruins, ogres around a ruined scout tower); DB spawns: Crushridge Ogre 2252, Brute 2253 in areas 282, 283, 1357; Mithril and Truesilver Deposits; Rizz Loosebolt 2684 (Engineering Supplies) in area 283'),
(3607, 1, 36, 7, 0, 0, 'The Uplands', 'North of Strahnbrad lie the Uplands, the farmlands that once fed the kingdom of Alterac. Today this is where the Syndicate is strongest. Sentries and saboteurs guard its camps, the shadow mages of the Argus Wake come and go, and Baron Vardus, a cold-hearted Alterac noble wanted by the Forsaken, has been seen among them. Not every house here belongs to a thief. Beside the lake lives Nancy Vishas, who waits anxiously at home whenever her husband''s work at the Monastery keeps him late, work the old man of the house calls cleansing the world of impure scum.', 'warcraft.wiki.gg/wiki/The_Uplands (bread basket of Alterac; Syndicate strongest); quest 537 description (Uplands where the Syndicate is strongest, north of Strahnbrad); quest 566 description (Vardus last spotted in the Uplands); quest 1051 description (Interrogator Vishas, wife Nancy along Lake Lordamere); creature_text 3984, 3985; DB spawns: Syndicate Sentry 2243, Saboteur 2245, Argus Shadow Mage 2318, Baron Vardus 2306, Nancy 3984, Grandpa Vishas 3985 in area 284; creature_text 3985 group 1 (cleansing the world of impure scum)'),
(3608, 1, 36, 8, 0, 0, 'Dandred''s Fold', 'On the western edge of the Uplands, a farm and manor house look down on a small harbor on Lordamere Lake, near the Misty Shore. This is Dandred''s Fold, the residence of Lord Aliden Perenolde, who styles himself lord of these lands and runs the Syndicate from here. Its grounds are guarded by the gang''s assassins and enforcers. Within the manor lives Perenolde''s mistress, Elysa, and close beside him stands a figure named Nagaz, a worn wooden chest at his feet. Snapping turtles crawl along the misty lakeshore below.', 'warcraft.wiki.gg/wiki/Dandred''s_Fold (farm and manor on the westernmost Uplands, harbor on Lordamere Lake, Misty Shore; Perenolde, Elysa, Nagaz, assassins and enforcers); quest 506 description (styled himself lord of this land); quest 507 description (manor on the shores of Lordamere Lake); DB spawns: Lord Aliden Perenolde 2423, Elysa 2317, Nagaz 2320 side by side; Syndicate Assassin 2246, Enforcer 2247; Snapjaw 2408 in areas 1682 and 1681; DB: Worn Wooden Chest 1765 beside Nagaz'),
(3609, 1, 36, 9, 0, 0, 'Lordamere Internment Camp', 'On a hill above the ruins of Dalaran stands the Lordamere Internment Camp, the only prison camp in the mountains, held by Dalaran''s shield guards and theurgists under Warden Belamoore. Its newest inmates are four Forsaken who deserted the Undercity after breaking into a secure vault and stealing four artifacts, pieces of bloodstone the royal apothecaries needed for their studies. The thieves fled to Dalaran, and the wizards quarantined them here. The Dark Lady wants her property returned and the deserters punished.', 'warcraft.wiki.gg/wiki/Lordamere_Internment_Camp (only internment camp in the mountains, hill overlooking the crater, Dalaranian forces, Warden Belamoore, four Forsaken deserters); quest 544 description and reward text; items 3688-3691 Bloodstone Oval, Marble, Shard, Wedge dropped by Kegan Darkmar 2414, Ricter 2411, Alina 2412, Dermot 2413; DB spawns: Dalaran Shield Guard 2271, Theurgist 2272, Warden Belamoore 2415 in area 278'),
(3610, 1, 36, 10, 0, 0, 'Dalaran Crater', 'Dalaran, city of the Kirin Tor, was laid waste in the Third War when the Burning Legion''s Archimonde was summoned before its walls. Afterward the survivors raised a vast violet dome over the heart of their ruined city, some say for protection in violent times, others for the solitude to study and plot. Around it, on the shore of Lordamere Lake, lie the ruined outskirts, ringed by broken walls. Summoners and their bound earth elementals patrol them, workers labor in the rubble, and an archmage or two keep watch over what is left.', 'warcraft.wiki.gg/wiki/Dalaran (survivors returned to rebuild the ruins and created a vast magical dome; the city later floated and moved to Northrend); warcraft.wiki.gg/wiki/Dalaran_Crater (before 3.0 a large purple dome players could not pass; Wrath: city lifted to Northrend leaving a gaping crater; dome remains, nearly transparent); warcraft.wiki.gg/wiki/Alterac_Mountains (Archimonde destroyed Dalaran); quest 545 description (vast magical dome, protection or solitude; ruined outskirts patrolled by wizards and elemental slaves); quest 557 (Bracers of Earth Binding); creature_text 2359 (elemental slave cracks, rubble); DB spawns: Dalaran Summoner 2358, Elemental Slave 2359, Dalaran Worker 2628, Ansirem 2543, Archmage Cedric 18165 in area 279'),
(3611, 1, 36, 11, 0, 0, 'Ravenholdt Manor', 'Hidden in the eastern hills above Hillsbrad, at the end of a winding mountain path northwest of Durnholde, stands Ravenholdt Manor, seat of the Assassin''s League. Outsiders are not welcome. The guards greet strangers with a warning to watch their backs, and the assassins on the grounds are quicker still to show their contempt. Within, Lord Jorach Ravenholdt presides over a guild of thieves and killers that admits only the most gifted. The manor has its own poison seller, a specialist engineer, a garden kept by a landscape architect, and a training arena that is the domain of the orc Master Kang. Its long war is with the Syndicate.', 'warcraft.wiki.gg/wiki/Ravenholdt_Manor (eastern Alterac, path northwest of Durnholde through a small cave; Simone Cantrell''s garden; Master Kang, orc, training arena); warcraft.wiki.gg/wiki/Ravenholdt (Assassin''s League, only those of extraordinary prowess, outsiders not welcome, conflict with the Syndicate); quest 8233 description (path in the mountains northwest of Durnholde); npc_text for gossip menus 4861, 4862 (Watch your back, stranger; You dare set foot inside Ravenholdt Manor, worm?); creature_template subnames: Smudge Thunderwood 6779 Poison Supplies, Zan Shivsproket 6777 Speciality Engineer, Simone Cantrell 7324 Landscape Architect; DB spawn: Master Kang 7325 in area 3486'),
(3612, 1, 36, 12, 0, 0, 'Chillwind Point', 'On the far eastern edge of the mountains, beside the river that runs north past Tarren Mill, a small rise is crowned by the ruins of an ancient troll site. Chill winds sweep down through a nearby ravine from the Plaguelands to the north, and give the point its name. Here the jungle troll hermit Bath''rah the Windwatcher keeps his camp and his cauldron, watching the ruins for a great elemental lord of the winds he calls Cyclonian. A red drake, Narillasanz, is sometimes seen in these eastern heights.', 'warcraft.wiki.gg/wiki/Chillwind_Point (small rise on the far eastern edge, ancient troll ruin, named for chill winds from the Western Plaguelands, Bath''rah); quest 1791 description (river along Tarren Mill''s eastern flank, ruins on its eastern bank); quest 1712 description (watching this site for Cyclonian, the wind lord); warcraft.wiki.gg/wiki/Narillasanz (red drake in the Alterac Mountains); DB spawns: Bath''rah 6176, Bath''rah''s Cauldron 89931, Narillasanz 2447 in area 1684'),
(3613, 2, 36, 1, 0, 0, 'Lord Aliden Perenolde', 'Aliden is the eldest son of Aiden Perenolde, the king who sold out the Alliance to the Horde. For two years after the Second War he tried to wash that stain from the family name, rising through the ranks at Durnholde under his mentor Aedelas Blackmoore. Then he left Blackmoore''s service for the mountains of Alterac and founded the Syndicate. From his manor at Dandred''s Fold he styles himself lord of the land, his mistress Elysa lives with him there, and Nagaz of the Argus Wake keeps close at his side.', 'warcraft.wiki.gg/wiki/Aliden_Perenolde (eldest son of Aiden; two years clearing the name; Durnholde under Blackmoore; left to run operations in Alterac); warcraft.wiki.gg/wiki/Kingdom_of_Alterac (Aliden founded the Syndicate); quest 507 description; warcraft.wiki.gg/wiki/Nagaz (positioned himself close to Perenolde); quest 506 description (styled himself lord of this land; mistress Elysa)'),
(3614, 2, 36, 2, 0, 0, 'Mug''thol', 'Mug''thol is warlord of the Crushridge ogres and master of the ruined city of Alterac. He rules from what is left of the old palace, with his loyal lieutenants Targ, Muckrake and Glommus at his side and the greedy ogre mage Grel''borg the Miser among his followers. He was not always his own master. The Banshee Queen once bound him to her will through a banshee''s possession and sent him into Alterac after a relic, the Crown of Will. He put the crown on, and it set him free. The Forsaken have not forgiven the insult, and Southshore fears his ogres will push down into the foothills next.', 'quest 495 description (sent to retrieve the Crown of Will, tried it on, resisted the possession); warcraft.wiki.gg/wiki/Mug''thol (possessed by a banshee sister, old palace, lieutenants, founded the Crushridge in the ruins); quest 519 description (Targ, Muckrake, Glommus loyal lieutenants); quest 520 description; quest 500 description (fear the ogres will move into the foothills)'),
(3615, 2, 36, 3, 2, 0, 'Gol''dir', 'Gol''dir is an orc warrior who led a band that the Warchief sent from Durotar into the Hillsbrad Foothills, to look into the human brigands called the Syndicate and to recover a small trinket Thrall wanted back. The mission went badly at Durnholde, where the Syndicate overwhelmed the orcs, and Gol''dir was carried off a captive. Now he lies chained in a locked room in Strahnbrad, calling out to anyone who comes near for the key to his chains, which the human jailor Borhuin carries.', 'quest 498 description (expedition, investigate the Syndicate, the trinket, overwhelmed at Durnholde); quest 533 description (held captive); quest 503 reward text (led the expedition from Durotar, forced to work hauling and digging; the news must reach whoever leads the group now); quest 506 description (Perenolde''s visit and plans, Elysa and the pendant); creature_text 2316 (inside the room; Borhuin has the key); item 3704 Rusted Iron Key from Jailor Borhuin 2431'),
(3616, 2, 36, 4, 0, 0, 'Baron Vardus', 'Baron Vardus is a noble of fallen Alterac, known for his cold heart and brutal methods, and a high-ranking member of the Syndicate. He keeps to the gang''s haunts in the mountains, around the ruins of Strahnbrad and the valley north of them, and he was last seen in the Uplands. The Forsaken want him dead for crimes against them, and High Executor Darthalia of Tarren Mill has posted a bounty on his head, to be paid to whoever brings proof of his death.', 'quest 523 description (noble of Alterac, cold heart, brutal practices, signed the contract; Strahnbrad or the valley north of it); quest 522 description (sealed with red wax and a distinctive signet ring); quest 566 description (crimes against the Forsaken, high-ranking member, Uplands, wanted dead); quest 523 reward text; warcraft.wiki.gg/wiki/Syndicate (high-ranking member)'),
(3617, 2, 36, 5, 0, 0, 'Nagaz', 'Nagaz keeps close beside Lord Aliden Perenolde in the manor at Dandred''s Fold, though what he is to the outlaw nobles of the Syndicate, and what he wants with them, is not plain to see. Strange company walks the gang''s camps of Strahnbrad and the Uplands besides: the shadow mages of the Argus Wake, who come and go on business of their own. A worn wooden chest stands beside Nagaz. In it lies a parchment bound by a spell that leaves it unreadable, but for the single word at its top: his own name.', 'warcraft.wiki.gg/wiki/Nagaz (positioned himself close to Perenolde); DB spawn: Nagaz 2320 beside Perenolde 2423 in Dandred''s Fold; Argus Shadow Mage 2318 in areas 280 and 284; quest 551 description (Ensorcelled Parchment, indecipherable but for the word Nagaz); gameobject 1765 Worn Wooden Chest (loot 1570 holds item 3706 at 100 percent) beside Nagaz; page_text 248, 257, 258, 259, 315 (Decrypted Letter: esoteric cipher, conscripted messenger, the bargain they will regret, Stromgarde, a nation of their own, the Third Host; signed Nagaz, Argus Heirophant, in Sargeras'' name; master appointed head of the Argus Wake by the Council); quest 537 description (Nagaz of the Argus Wake; find him and kill him; envoys of the Argus Wake); warcraft.wiki.gg/wiki/Argus_Wake (hierophant)'),
(3618, 2, 36, 6, 0, 0, 'Lord Jorach Ravenholdt', 'Lord Jorach Ravenholdt is master of the Assassin''s League, the order of thieves and killers that gathers at Ravenholdt Manor. After the Third War he took up the hunt for the Syndicate in these mountains, and the League has fought the gang ever since. With far fewer blades than their enemy has members, the League pays skilled rogues to shame Syndicate members by stealing their emblems. His grand master, Fahrad, trains the guild''s rogues and sends anyone else away with a threat. Jorach greets those he needs with open arms and rewards loyal service generously, but keeps his own secrets close: the contents of a sealed azure bag he once lost were, he said, a private matter.', 'warcraft.wiki.gg/wiki/Jorach_Ravenholdt (leader of the League, hunted the Syndicate after the Third War, Sealed Azure Bag); warcraft.wiki.gg/wiki/Ravenholdt (outnumbered by the Syndicate, emblems stolen to shame members); quest 6701 (Syndicate Emblems); quests 8233, 8234, 8236 (welcome, private matter, golden glow from the bag); npc_text 4838, 4839 (Fahrad gossip menu 3984); quest 6701 starts from Ravenholdt Guard 6766'),
(3619, 2, 36, 7, 1, 0, 'Archmage Ansirem Runeweaver', 'Ansirem Runeweaver is a senior archmage of the Kirin Tor, and by the Third War held a seat on the Council of Six that governed Dalaran. When the Scourge came and Antonidas fell, Ansirem fought outside the city walls against Arthas and the undead while Kel''Thuzad called down the demon lord Archimonde. He keeps his watch now beside the ruins of Dalaran on the shore of Lordamere Lake. His learning ranges far, and like most of his kind he can hardly resist a magical puzzle.', 'warcraft.wiki.gg/wiki/Ansirem_Runeweaver (Kirin Tor, Council of Six, fought outside Dalaran while Kel''Thuzad summoned Archimonde); quest 602 description and reward text (some mages remained; tome on the Gurubashi Empire; mages cannot resist a magical puzzle); quest 603 description (willful daughter Catelyn ran off to Booty Bay to be a pirate); creature_text 2543'),
(3620, 2, 36, 8, 0, 8, 'Archmage Cedric', 'Archmage Cedric is an agent of the Violet Eye, the order the Kirin Tor of Dalaran assigned long ago to keep watch over Karazhan and its master Medivh, in case things got out of hand, as they soon did. He waits among the ruined outskirts of Dalaran on the shore of Lordamere Lake, unmoved by the desolation around him and certain that Dalaran is as powerful as ever. Reports from the Eye''s agents in Deadwind Pass come to him, and he is not pleased to find outsiders trusted with the order''s secrets.', 'quest 9826 description and completion text (Violet Eye, agents of the Kirin Tor watching Karazhan and Medivh; Cedric in the outskirts of Dalaran; that old fool); quest 9829 description (Karazhan sealed, lost agents, demonic emanation, Khadgar alive in Shattrath); quest 9860 description and reward text (Legion renewing its attacks, the badge of the Violet Eye); npc_text 9241 (gossip menu 7593: do not be fooled by the ruins, Dalaran is as powerful as ever); warcraft.wiki.gg/wiki/Archmage_Cedric (added in patch 2.0.1, The Burning Crusade); quest_template Flags 128 (Burning Crusade flag) on 9826, 9829, 9860'),
(3621, 2, 36, 9, 0, 0, 'Bath''rah the Windwatcher', 'Bath''rah is a jungle troll shaman and weaponcrafter who has taken up a hermit''s life at the troll ruins of Chillwind Point. For ages, he says, he has watched the site, waiting for a champion able to bring down Cyclonian, the lord of the winds who can be called there. Those who gather what his summoning needs may face the elemental, and from its whirlwind heart Bath''rah will forge a weapon. Lately the spirits of the place have turned against him, and he has sought a spirit totem, strengthened with troll voodoo, to guard his sleep.', 'warcraft.wiki.gg/wiki/Bath''rah_the_Windwatcher (jungle troll, weaponcrafter turned hermit, Chillwind Point); quest 1791 description (skilled weapon maker and powerful shaman); quests 1712, 1713, 1792 (Cyclonian, whirlwind heart, weapon); quests 8412, 8413 (spirits no longer like him, spirit totem, voodoo, a full night''s rest)'),
(3622, 2, 36, 10, 0, 0, 'Nancy Vishas', 'Nancy Vishas lives in a house in the Uplands near Lake Lordamere, where she waits anxiously for her husband to come home from his work at the Monastery. He is late again, she frets, though he must be overwhelmed with work, and she goes outside to look for him when she can bear the wait no longer. An old man called Grandpa Vishas shares the house and has no patience for her fretting: cleansing the world of impure scum, he reminds her, is not an easy job, and someone has to do it.', 'quest 1051 description and reward text; creature_text 3984 (Sidney is late, work at the Monastery), 3985 (He''s your husband, woman); DB spawns: Nancy Vishas 3984 and Grandpa Vishas 3985 in area 284; Monika Sengutz 3982 in Tarren Mill; warcraft.wiki.gg/wiki/Interrogator_Vishas (wife Nancy, cottage on Lordamere Lake)'),
(3627, 3, 36, 5, 2, 0, 'The Bloodstone Thieves', 'Some months ago four Forsaken deserted the Undercity, and before they fled they broke into a secure vault and stole four artifacts the royal apothecaries needed for their studies. They ran to Dalaran, and the wizards locked them away in the Lordamere Internment Camp. Magus Wordeen Voidglare, who had come to Tarren Mill only to research, found himself charged with getting the artifacts back for the Dark Lady. The Magus has his own interest in Dalaran''s magic as well, and Keeper Bel''varil, who serves him, gathers the stone tokens the wizards use to command their elementals, so that the Magus may unlock their secrets.', 'quests 544, 545, 556, 557 (descriptions and reward texts); creature_queststarter: Magus Wordeen Voidglare 2410 starts 544, 545; Keeper Bel''varil 2437 starts 556, 557');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(3601, 1, 0, 255, 'For a last mug of Southshore stout, the dying Valik hands over a missive he will no longer need. It orders him to guard a slave, called only it, until the others return, since the captive is no longer safe in the camp. It is to be moved north, far from any chance of being seen, for the writer calls the slave''s people brutal animals and wants to give them no reason to rally and attack in force.', 'quest 535 reward text (Here, take this); quest_template 535 RewardItem1 3601 Syndicate Missive; page_text 249 (Syndicate Missive addressed to Valik)'),
(3610, 1, 0, 12, 'For now the dome stands whole, a wall of violet light that no outsider can pass. Behind it, out of sight of the world, the surviving Kirin Tor are said to be rebuilding the heart of their city.', 'warcraft.wiki.gg/wiki/Dalaran (survivors returned to rebuild the ruins and created a vast magical dome); warcraft.wiki.gg/wiki/Dalaran_Crater (before patch 3.0.2 players could not walk through the barrier); quest 602 description (the mages succeeded in rebuilding their city before moving it); DB spawns: Dalaran Worker 2628 in area 279'),
(3610, 2, 13, 255, 'In time the Kirin Tor finished rebuilding their city behind the dome and lifted it whole into the skies of Northrend. All that remains on the lakeshore is a gaping crater beneath a dome now faded nearly to nothing, open to anyone who walks in. Some mages stayed behind among the ruins rather than follow the city north.', 'quest 602 description (rebuilt and moved to Northrend, massive crater; some mages remained); warcraft.wiki.gg/wiki/Dalaran_Crater (Wrath: gaping crater, dome nearly transparent and permitting entry; added in patch 3.0.2)'),
(3613, 1, 0, 255, 'Word of him came out of Strahnbrad with the captive orc Gol''dir, whom Perenolde visited to boast. He means to make slaves of the orcs who stand against him, as his father and Blackmoore once planned, and the girl at his side, his mistress Elysa, wears around her neck the very pendant the Warchief sent his orcs to recover. In Tarren Mill the Horde now wants him dead and the pendant taken back.', 'quest 506 description (Gol''dir''s news: plans to enslave orcs, mistress Elysa, the pendant); quest 507 description (Perenolde must be killed, retrieve the pendant)'),
(3613, 2, 0, 255, 'Lord Aliden Perenolde is slain in his own manor at Dandred''s Fold, above the shore of Lordamere Lake. The son of Alterac''s traitor king, who would have made himself lord of the land his father lost, dies among the outlaws he gathered to win it back.', 'KILL 2423 at Dandred''s Fold; quest 507 description (manor on the shores of Lordamere Lake)'),
(3614, 1, 0, 255, 'Mug''thol falls at last amid the ruins of the old palace he made his seat. The warlord who threw off the Dark Lady''s will by putting on the Crown of Will dies among the broken halls of Alterac, and the Crushridge he led into the dead kingdom''s capital are left without their master.', 'KILL 2257 in the Ruins of Alterac; warcraft.wiki.gg/wiki/Mug''thol (based in the ruins of the old palace, founded the Crushridge in the ruins); quest 495 description (Mug''Thol and his ogre warband sent to Alterac); warcraft.wiki.gg/wiki/Mug''thol (after the crown freed him he established himself and his band in the ruins of Alterac as the Crushridge, citing The Crown of Will)'),
(3615, 1, 0, 255, 'Freed at last, Gol''dir waves his own suffering aside, though his captors kept him hauling burdens and digging. What matters is his news. Lord Aliden Perenolde, leader of the Syndicate, came to boast that he would make slaves of the orcs who oppose him, just as his father and the despised Blackmoore once planned, and he brought his mistress, a wisp of a girl named Elysa. Around her neck hung the pendant the Warchief desires. Gol''dir sends the word back to Tarren Mill, and stays behind to settle his own business.', 'quest 503 reward text; quest 506 description (offered by Gol''dir on the turn-in of 503)'),
(3616, 1, 0, 255, 'Southshore has its own score with him. A contract for the murder of Magistrate Henry Maleb, sealed in red wax with a distinctive signet ring, turned up among the Syndicate, and it bears the signature of Baron Vardus. Maleb is not surprised to find the baron behind it, and wants him found and brought to justice.', 'quest 522 description; quest 523 description (offered on the turn-in of 522)'),
(3616, 2, 0, 255, 'Baron Vardus is hunted down at last among the Syndicate haunts of the Uplands and slain. For all his cold heart and brutal methods, the baron falls like any common cutthroat, and the Syndicate has one high-ranking member fewer.', 'KILL 2306 in the Uplands; quest 566 description'),
(3617, 1, 0, 255, 'A letter of his, taken from a Syndicate camp and decoded, shows what he is. Nagaz is the Argus Wake''s hierophant in Alterac, the hand of a master whom the Council made head of the Wake, and he signs in the name of Sargeras. He mocks the Syndicate''s bargain as one they will regret. He means to make them rulers of Alterac again, turn them on Stromgarde, and win the Wake a nation from which to prepare the way for the Third Host of the Legion. Southshore now wants his head.', 'page_text 248, 257, 258, 259, 315 (Decrypted Letter); quest 537 description (offered on the turn-in of 525, after the letter is decoded)'),
(3617, 2, 0, 255, 'Nagaz is slain in the manor at Dandred''s Fold, beside the Syndicate lord he kept so close. Yet the shadow mages of the Argus Wake still walk the Syndicate camps of Strahnbrad and the Uplands.', 'KILL 2320 at Dandred''s Fold; quest 537 description (envoys of the Argus Wake); DB spawns: Argus Shadow Mage 2318 in areas 280 and 284'),
(3619, 1, 0, 255, 'Shown a bag of water elemental bracers and asked about the Stone of the Tides, Ansirem admits that years ago he wrote a tome on the legends of the Gurubashi Empire, and that he knows a good deal about the Stone. At least one of the bracers still bears a magical residue, and he sets to analyzing it at once.', 'quest 602 reward text'),
(3619, 2, 13, 255, 'Now that Dalaran has risen into the skies of Northrend, Ansirem is among the few mages who stayed behind at the crater it left on the shore of Lordamere Lake, rather than follow the city north.', 'quest 602 description (rebuilt and moved to Northrend; some mages remained here)'),
(3620, 1, 0, 255, 'Alturus''s report unsettles him. Karazhan sealed itself off long ago, and the Eye''s agents inside were never heard from again; now a demonic emanation stirs within. Only Medivh or his apprentice Khadgar was thought able to open the tower again, and Khadgar, long presumed dead, has been found alive in Shattrath City. Cedric sends the report on to him.', 'quest 9829 description'),
(3620, 2, 0, 255, 'When Alturus has told him all that came of the Eye''s work at the tower, Cedric warns that it is not the end. While Karazhan stays sealed to outsiders, it is only a matter of time before the Legion renews its attacks while the Eye stands powerless. To those who have aided it he offers a badge bearing the Violet Eye''s symbol, and the responsibility that comes with it.', 'quest 9860 description and reward text (ends at Cedric 18165)'),
(3621, 1, 0, 255, 'The reagents are gathered and the ritual performed, and Cyclonian is summoned and brought down. His whirlwind heart is carried back to Bath''rah, who rejoices and keeps his word: he stands ready to set the heart within a weapon of the champion''s choosing, so that the wind lord''s power lives on in it.', 'quest 1712 reward text; quest 1713 description and reward text; quest 1792 reward text (auto-complete, follows 1713)'),
(3622, 1, 0, 255, 'Her husband is the Scarlet Crusade''s Interrogator Vishas, and his work at the Monastery is torture. One of his victims, the Forsaken Vorrel Sengutz, was tormented for weeks and saw his own wedding ring taken and given to Nancy, of whom the interrogator loved to brag. Broken past saving, Vorrel''s last wish was that she be found and slain, and the ring returned to his wife Monika in Tarren Mill.', 'quest 1051 description'),
(3622, 2, 0, 255, 'The ring comes home to Tarren Mill. Monika Sengutz grieves for a good mate whose existence was so troubled, gone now beyond any return to undeath. She curses the humans, and takes what solace she can from the revenge taken in his name.', 'quest 1051 reward text (ends at Monika Sengutz 3982)'),
(3627, 1, 0, 255, 'The four artifacts come back to the Forsaken, sorely missed, and Kegan Darkmar and the other betrayers meet their justice. Then the Magus turns to Dalaran itself. Whatever the wizards meant by their vast dome, protection or solitude, he cares only that the ruined outskirts may hide magical treasures, and he wants the patrols of wizards and elemental slaves thinned.', 'quest 544 reward text; quest 545 description (offered on the turn-in of 544); items 3688-3691 Bloodstone Oval, Marble, Shard, Wedge dropped by Kegan Darkmar 2414, Ricter 2411, Alina 2412, Dermot 2413'),
(3627, 2, 0, 255, 'The summoners and their elemental slaves are hunted until their numbers fall, and the Magus judges the ruins around Dalaran safe enough to search at last, so long as the searchers are careful.', 'quest 545 reward text'),
(3627, 3, 0, 255, 'The tokens prove faded, their magic gone, which suits the Magus well, for his first experiments are best made on inert specimens. Bel''varil knows he will soon want their counterpart too: the bracers of binding set around the wrists of the elementals themselves, which bind them into a mage''s service.', 'quest 556 reward text (prerequisite of 557); quest 557 description');
